const IMPLANT_WIDTH = 51;
const IMPLANT_HEIGHT = 72;

/** Transform positionnant l'implant dans la zone radiculaire d'une viewBox donnée. */
export function implantTransform(viewBox) {
  const parts = viewBox.split(' ').map(Number);
  const width = parts[2] || 60;
  const height = parts[3] || 130;
  const rootAreaTop = height * 0.02;
  const rootAreaBottom = height * 0.7;
  const scale = (rootAreaBottom - rootAreaTop) / IMPLANT_HEIGHT;
  const translateX = (width - IMPLANT_WIDTH * scale) / 2;
  return `translate(${translateX}, ${rootAreaTop}) scale(${scale})`;
}

/** Groupe SVG de l'implant (chemin + remplissage), à insérer dans un `<svg>` de la dent. */
export function implantSvg(viewBox, fill, opacity = 1) {
  return `<g class="dental-implant" transform="${implantTransform(viewBox)}">
    <path d="${IMPLANT_PATH}" class="implant-stroke" fill="none" stroke-width="0.6" vector-effect="non-scaling-stroke" stroke-linejoin="round" opacity="${opacity}"/>
    <path d="${IMPLANT_PATH}" fill="${fill}" fill-opacity="0.15" stroke="none"/>
  </g>`;
}
